using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using TraceCommons.Interop.Shell;
using Xunit;

namespace TraceCommons.Interop.Tests;

/// <summary>
/// The Mac's flat glass tokens as the Windows shell carries them (spec W5):
/// <c>Shell/GlassTokens.g.cs</c> and <c>Themes/GlassTokens.xaml</c>, both
/// generated by <c>scripts/design-tokens/generate.py</c>.
/// </summary>
/// <remarks>
/// Values are pinned to the Swift at the base (GlassTokens.swift, the
/// generated Mac constants, flat theme), never to the generator's own
/// output. Contrast is measured on the colours the shell paints: every text
/// role at 4.5:1 and every indicator at 3:1 on every tier it sits on,
/// focused and unfocused, and over Mica the pane's veil composited over a
/// black and a white desktop (checklist D1, D2, D4).
/// </remarks>
public class GlassTokensTests
{
    // GlassTokens.swift:693-703, Motion.
    [Fact]
    public void MotionIsTheMacs()
    {
        Assert.Equal(0.15, GlassTokens.Motion.Fast);
        Assert.Equal(0.22, GlassTokens.Motion.Standard);
        Assert.Equal(0.3, GlassTokens.Motion.Slow);
        Assert.Equal(0.18, GlassTokens.Motion.Reveal);
        Assert.Equal(0.25, GlassTokens.Motion.Slide);
        Assert.Equal(0.8, GlassTokens.Motion.Spin);
        Assert.Equal(1.6, GlassTokens.Motion.Pulse);
        Assert.Equal((0.2, 0.8, 0.2, 1.0), (GlassTokens.Motion.EaseX1, GlassTokens.Motion.EaseY1, GlassTokens.Motion.EaseX2, GlassTokens.Motion.EaseY2));
    }

    // GlassTokens.swift:477-480, Radius, the flat values.
    [Fact]
    public void RadiiAreTheFlatThemes()
    {
        Assert.Equal(20, GlassTokens.Radius.Pane);
        Assert.Equal(16, GlassTokens.Radius.Card);
        Assert.Equal(14, GlassTokens.Radius.CardQuiet);
        Assert.Equal(11, GlassTokens.Radius.Control);
    }

    // GlassTokens.swift:567-602 and :678.
    [Fact]
    public void ControlSizesAreTheMacs()
    {
        Assert.Equal((40.0, 24.0), (GlassTokens.Size.ToggleWidth, GlassTokens.Size.ToggleHeight));
        Assert.Equal((38.0, 22.0), (GlassTokens.Size.WatchSwitchWidth, GlassTokens.Size.WatchSwitchHeight));
        Assert.Equal(7, GlassTokens.Size.Dot);
        Assert.Equal(8, GlassTokens.Size.ModalScrimBlur);
        Assert.Equal((12.0, 1.5), (GlassTokens.Size.Spinner, GlassTokens.Size.SpinnerStroke));
        Assert.Equal(12, GlassTokens.Size.SkeletonHeight);
        Assert.Equal(0.5, GlassTokens.Opacity.SkeletonDim);
    }

    // GlassTokens.swift:178-180 (tabEmber, tabEmberHalo, flat) and the flat
    // tier fills the Linux painted palette also draws.
    [Fact]
    public void TheEmberIsTheFlatBlue()
    {
        Assert.Equal("#FF0091FD", GlassTokens.Brushes(dark: true)["TcGlassTabEmberColor"]);
        Assert.Equal("#FF056BDC", GlassTokens.Brushes(dark: false)["TcGlassTabEmberColor"]);
        // tabEmberHalo flat: #0091FD at 0.31 dark, #056BDC at 0.28 light.
        Assert.Equal("#4F0091FD", GlassTokens.Brushes(dark: true)["TcGlassTabEmberHaloColor"]);
        Assert.Equal("#47056BDC", GlassTokens.Brushes(dark: false)["TcGlassTabEmberHaloColor"]);
    }

    public static IEnumerable<object[]> Schemes() => new[] { new object[] { true }, new object[] { false } };

    private static readonly string[] TextTiers =
    {
        "TcGlassPaneBrush", "TcGlassCardBrush", "TcGlassCardQuietBrush", "TcGlassControlBrush",
        "TcGlassPopoverBrush", "TcGlassMenuBrush", "TcGlassNodeCardBrush",
    };

    [Theory]
    [MemberData(nameof(Schemes))]
    public void EveryInkReadsOnEveryTierFocusedAndNot(bool dark)
    {
        IReadOnlyDictionary<string, string> b = GlassTokens.Brushes(dark);
        var failures = new List<string>();
        foreach (string tier in TextTiers.Concat(TextTiers.Select(Inactive)))
        {
            foreach ((string ink, double floor) in new[]
                     {
                         ("TcGlassInkBrush", 4.5), ("TcGlassInkSecondaryBrush", 4.5), ("TcGlassInkTertiaryBrush", 4.5),
                         ("TcStatusOnTextBrush", 4.5), ("TcStatusAskTextBrush", 4.5), ("TcStatusOutsideTextBrush", 4.5),
                         ("TcAccentTextBrush", 4.5), ("TcGlassTabEmberBrush", 3.0), ("TcGlassStatusOnBrush", 3.0),
                         ("TcGlassStatusAskBrush", 3.0), ("TcGlassStatusOutsideBrush", 3.0),
                     })
            {
                double ratio = Contrast(b[ink], b[tier]);
                if (ratio < floor)
                {
                    failures.Add($"{(dark ? "dark" : "light")}: {ink} {b[ink]} on {tier} {b[tier]} is {ratio:F2}:1");
                }
            }
        }

        Assert.Empty(failures);
    }

    [Theory]
    [MemberData(nameof(Schemes))]
    public void LabelsOnFillsRead(bool dark)
    {
        IReadOnlyDictionary<string, string> b = GlassTokens.Brushes(dark);
        Assert.True(Contrast(b["TcGlassCtaInkBrush"], b["TcGlassCtaBrush"]) >= 4.5);
        Assert.True(Contrast(b["TcGlassSelectedInkBrush"], b["TcGlassControlSelectedBrush"]) >= 4.5);
        Assert.True(Contrast(b["TcGlassToggleKnobOnBrush"], b["TcGlassToggleOnBrush"]) >= 3.0);
        // A hover wash must show against the control it lights (1.1:1, the
        // Linux floor in generate.py's glass_palette).
        Assert.True(Contrast(b["TcGlassControlHoverBrush"], b["TcGlassControlBrush"]) >= 1.1);
    }

    /// <summary>
    /// Over Mica the pane is the translucent veil; whatever the desktop
    /// behind, from black to white, every ink still reads at 4.5:1 on it,
    /// focused and not (checklist D4: the two-sided table).
    /// </summary>
    [Theory]
    [MemberData(nameof(Schemes))]
    public void InkReadsThroughTheMaterialOverABlackOrWhiteDesktop(bool dark)
    {
        IReadOnlyDictionary<string, string> b = GlassTokens.Brushes(dark);
        var failures = new List<string>();
        foreach (string veil in new[] { "TcGlassPaneOverMaterialBrush", "TcGlassPaneOverMaterialInactiveBrush" })
        {
            Assert.NotEqual("FF", b[veil].Substring(1, 2));
            foreach (string desktop in new[] { "#FF000000", "#FFFFFFFF" })
            {
                string ground = Over(b[veil], desktop);
                foreach (string ink in new[] { "TcGlassInkBrush", "TcGlassInkSecondaryBrush" })
                {
                    double ratio = Contrast(b[ink], ground);
                    if (ratio < 4.5)
                    {
                        failures.Add($"{(dark ? "dark" : "light")}: {ink} on {veil} over {desktop} is {ratio:F2}:1");
                    }
                }
            }
        }

        Assert.Empty(failures);
    }

    /// <summary>
    /// The XAML's three theme dictionaries name the same keys (checklist D2:
    /// every brush lands with its dark, light and High Contrast value), each
    /// tier has its unfocused twin, and every brush the dark and light
    /// dictionaries carry is the generated C#'s, colour for colour.
    /// </summary>
    [Fact]
    public void EveryKeyHasItsDarkLightHighContrastAndInactiveForms()
    {
        string xaml = Source("GlassTokens.xaml.txt");
        Dictionary<string, string> dark = Block(xaml, "Default");
        Dictionary<string, string> light = Block(xaml, "Light");
        HashSet<string> contrast = Keys(xaml, "HighContrast");

        Assert.Equal(dark.Keys.OrderBy(k => k), light.Keys.OrderBy(k => k));
        Assert.Equal(dark.Keys.OrderBy(k => k), contrast.OrderBy(k => k));
        foreach (string tier in new[] { "Pane", "Card", "CardQuiet", "Well", "Control", "ControlSelected", "Popover", "Menu", "NodeCard" })
        {
            Assert.Contains($"TcGlass{tier}Brush", dark.Keys);
            Assert.Contains($"TcGlass{tier}InactiveBrush", dark.Keys);
        }

        foreach ((Dictionary<string, string> block, bool isDark) in new[] { (dark, true), (light, false) })
        {
            foreach ((string key, string value) in block)
            {
                Assert.Equal(GlassTokens.Brushes(isDark)[key], value);
            }
        }
    }

    /// <summary>
    /// The keys the views bind to read the glass palette: the window's
    /// ground is the painted pane and a card the painted card.
    /// </summary>
    [Theory]
    [MemberData(nameof(Schemes))]
    public void TheViewsKeysAreTheGlassTiers(bool dark)
    {
        IReadOnlyDictionary<string, string> b = GlassTokens.Brushes(dark);
        Assert.Equal(b["TcGlassPaneBrush"], b["TcWindowBackgroundBrush"]);
        Assert.Equal(b["TcGlassPaneBrush"], b["TcChromeBackgroundBrush"]);
        Assert.Equal(b["TcGlassCardBrush"], b["TcSurfaceCardBrush"]);
        Assert.Equal(b["TcGlassWellBrush"], b["TcSurfaceInsetBrush"]);
        Assert.Equal(b["TcGlassInkBrush"], b["TcInkPrimaryBrush"]);
        Assert.Equal(b["TcGlassRuleBrush"], b["TcHairlineBrush"]);
    }

    /// <summary>
    /// The flat dark pane over its opaque base: paneFill (#FFFFFF at 0.04)
    /// over paneOpaque #0D1124 (GlassTokens.swift paneFill flat stops,
    /// paneOpaque flat), rounded per channel: #171B2D. Light: paneFill
    /// #F4F6F9 at 0.08 over #F2F3F6 is #F2F3F6.
    /// </summary>
    [Fact]
    public void ThePaneIsPaneFillOverItsOpaqueBase()
    {
        Assert.Equal("#FF171B2D", GlassTokens.Brushes(dark: true)["TcGlassPaneBrush"]);
        Assert.Equal("#FFF2F3F6", GlassTokens.Brushes(dark: false)["TcGlassPaneBrush"]);
    }

    internal static string Inactive(string key) => key.Substring(0, key.Length - "Brush".Length) + "InactiveBrush";

    internal static string Over(string argb, string ground)
    {
        double a = Channel(argb, 1) / 255.0;
        int Mix(int i) => (int)Math.Round(Channel(argb, i) * a + Channel(ground, i) * (1 - a));
        return $"#FF{Mix(3):X2}{Mix(5):X2}{Mix(7):X2}";
    }

    private static int Channel(string argb, int offset) =>
        int.Parse(argb.AsSpan(offset, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture);

    internal static double Contrast(string a, string b)
    {
        double la = Luminance(a), lb = Luminance(b);
        return (Math.Max(la, lb) + 0.05) / (Math.Min(la, lb) + 0.05);
    }

    private static double Luminance(string argb)
    {
        Assert.Equal("FF", argb.Substring(1, 2));
        double C(int offset)
        {
            double v = Channel(argb, offset) / 255.0;
            return v <= 0.04045 ? v / 12.92 : Math.Pow((v + 0.055) / 1.055, 2.4);
        }

        return 0.2126 * C(3) + 0.7152 * C(5) + 0.0722 * C(7);
    }

    private static Dictionary<string, string> Block(string xaml, string theme)
    {
        var map = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (Match m in Regex.Matches(ThemeBlock(xaml, theme), "x:Key=\"(\\w+)\"(?: Color=\"(#[0-9A-F]{8})\" />|>(#[0-9A-F]{8})</Color>)"))
        {
            map[m.Groups[1].Value] = m.Groups[2].Success && m.Groups[2].Value.Length > 0 ? m.Groups[2].Value : m.Groups[3].Value;
        }

        Assert.NotEmpty(map);
        return map;
    }

    private static HashSet<string> Keys(string xaml, string theme) =>
        Regex.Matches(ThemeBlock(xaml, theme), "x:Key=\"(\\w+)\"").Select(m => m.Groups[1].Value).ToHashSet(StringComparer.Ordinal);

    private static string ThemeBlock(string markup, string theme)
    {
        Match block = Regex.Match(markup, $"<ResourceDictionary x:Key=\"{theme}\">(.*?)</ResourceDictionary>", RegexOptions.Singleline);
        Assert.True(block.Success, $"a {theme} theme dictionary");
        return block.Groups[1].Value;
    }

    private static string Source(string name)
    {
        string root = Path.Combine(AppContext.BaseDirectory, "shell-source");
        string? path = Directory.Exists(root)
            ? Directory.EnumerateFiles(root, name, SearchOption.AllDirectories).FirstOrDefault()
            : null;
        Assert.True(path is not null, $"{name} is copied into the test output");
        return File.ReadAllText(path!).Replace("\r\n", "\n", StringComparison.Ordinal);
    }
}
